import { useState } from "react";
import NoteContext from "./noteContext";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = []

  const [notes, setNotes] = useState(notesInitial);

  //fetch a note
  const getNotes = async() => {
    try {
      console.log("Fetching notes...");
      const response = await fetch(`${host}/api/notes/fetchallnotes`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        }
      });
      
      console.log("Fetch response status:", response.status);
      const json = await response.json()
      console.log("Fetched notes:", json)
      
      if (response.ok) {
        setNotes(json)
      } else {
        console.error("Failed to fetch notes:", json);
      }
    } catch (error) {
      console.error("Error fetching notes:", error);
    }
  }

  //Add a note
  const addNote = async(title, description, tag) => {
    try {
      console.log("Adding note with data:", { title, description, tag });
      
      const response = await fetch(`${host}/api/notes/addnote`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        },
        body: JSON.stringify({title, description, tag}),
      });

      console.log("Add response status:", response.status);
      const json = await response.json();
      console.log("Add response data:", json);
      
      if (response.ok) {
        // Use the actual response from API
        setNotes(prevNotes => [...prevNotes, json]);
        console.log("Note added successfully to state");
      } else {
        console.error("Failed to add note:", json);
      }
    } catch (error) {
      console.error("Error adding note:", error);
    }
  };

  //Delete a Note
  const deleteNote = async(id) => {
    try {
      console.log("Deleting note with id:", id);
      
      const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        }
      });
      
      console.log("Delete response status:", response.status);
      const json = await response.json();
      console.log("Delete response:", json)
      
      if (response.ok) {
        const newNotes = notes.filter((note) => note._id !== id);
        setNotes(newNotes);
        console.log("Note deleted successfully from state");
      } else {
        console.error("Failed to delete note:", json);
      }
    } catch (error) {
      console.error("Error deleting note:", error);
    }
  };

  //Update a note
  const editNote = async (id, title, description, tag) => {
    try {
      console.log("Editing note with:", { id, title, description, tag });
      
      const response = await fetch(`${host}/api/notes/editNote/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        },
        body: JSON.stringify({title, description, tag}),
      });
      
      console.log("Edit response status:", response.status);
      const json = await response.json();
      console.log("Edit response data:", json);

      if (response.ok) {
        // Create a new notes array with the updated note
        const updatedNotes = notes.map((note) => {
          if (note._id === id) {
            return { ...note, title, description, tag };
          }
          return note;
        });
        
        console.log("Original notes:", notes);
        console.log("Updated notes:", updatedNotes);
        
        setNotes(updatedNotes);
        console.log("Note updated successfully in state");
        
        // Verify the update worked
        setTimeout(() => {
          console.log("Notes after state update:", notes);
        }, 100);
        
      } else {
        console.error("Failed to update note:", json);
      }
    } catch (error) {
      console.error("Error updating note:", error);
    }
  };

  return (
    <NoteContext.Provider value={{ notes, addNote, deleteNote, editNote, getNotes }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
